def solve():
    import datetime
    dates = ["2026-10-19", "2026-10-20", "2026-10-21", "2026-10-22"]
    party_size = 6
    best_date = None
    best_time = None

    for date in dates:
        avail = check_availability(date=date, party_size=party_size)
        times = avail.get("times", [])
        valid_times = [t for t in times if t > "18:00"]
        if valid_times:
            earliest_time = min(valid_times)
            if best_time is None or earliest_time < best_time:
                best_time = earliest_time
                best_date = date
            elif earliest_time == best_time:
                if best_date is None or date < best_date:
                    best_date = date

    return best_date, best_time

