def get_payment_stats(account_id):
    from datetime import datetime
    payments_data = lookup_payment_history(account_id=account_id)
    payments = payments_data.get('payments', [])

    total_paid = 0.0
    late_count = 0
    max_payment = 0.0

    for p in payments:
        paid_date = datetime.strptime(p['paid'], '%Y-%m-%d')
        if paid_date.year == 2025:
            total_paid += p['amount']
            if p['paid'] > p['due']:
                late_count += 1
            if p['amount'] > max_payment:
                max_payment = p['amount']

    return {
        "total_paid": total_paid,
        "late_count": late_count,
        "max_payment": max_payment
    }

print(get_payment_stats('ACME-9000'))
